let start = startofday(ago(7d));
let bins = range Day from start to startofday(now()) step 1d;
let data = requests
| where timestamp > ago(7d)
| summarize Views = count() by Day = bin(timestamp, 1d);
bins
| join kind=leftouter data on Day
| project timestamp = Day, Views = coalesce(Views, 0)
| order by timestamp asc

let start = startofday(ago(7d));
let bins = range Day from start to startofday(now()) step 1d;
let data = requests
| where timestamp > ago(7d)
| extend op = tostring(column_ifexists('operation_Id', ''))
| summarize Users = dcountif(op, isnotempty(op)) by Day = bin(timestamp, 1d);
bins
| join kind=leftouter data on Day
| project timestamp = Day, Users = coalesce(Users, 0)
| order by timestamp asc
